#include "ribo/Metrics.h"
#include "ribo/Runtime.h"
#include "ribo/Json.h"
#include <cctype>
#include <fstream>
#include <iostream>
#include <string>
#include <string_view>
struct Case { std::string id, sequence, reference, topology, source; int minLoop = 3, stemLength = 1, stem1Length = 0, stem2Length = 0, pairScore = 1, wobbleScore = 0; };
static std::string clean(std::string s) { std::string out; for (const auto c : s) if (c != '>' && !std::isspace(static_cast<unsigned char>(c))) out += c; return out; }
static std::string value(std::string_view l) { const auto p = l.find(':'); if (p == std::string_view::npos) return {}; auto s = std::string(l.substr(p + 1)); while (!s.empty() && std::isspace(static_cast<unsigned char>(s.front()))) s.erase(s.begin()); if (s.size() >= 2 && s.front() == '"' && s.back() == '"') s = s.substr(1, s.size() - 2); return s; }
static Case readCase(const char *path) { std::ifstream in(path); Case c; std::string l; while (std::getline(in, l)) { const auto v = value(l); if (l.starts_with("id:")) c.id = v; else if (l.starts_with("sequence:")) c.sequence = clean(v); else if (l.starts_with("reference_structure:")) c.reference = clean(v); else if (l.starts_with("reference_topology:")) c.topology = v; else if (l.starts_with("source:")) c.source = v; else if (l.starts_with("min_loop:")) c.minLoop = std::stoi(v); else if (l.starts_with("stem_length:")) c.stemLength = std::stoi(v); else if (l.starts_with("stem1_length:")) c.stem1Length = std::stoi(v); else if (l.starts_with("stem2_length:")) c.stem2Length = std::stoi(v); else if (l.starts_with("pair_score:")) c.pairScore = std::stoi(v); else if (l.starts_with("wobble_score:")) c.wobbleScore = std::stoi(v); } return c; }
int main(int argc, char **argv) { const bool json = argc == 3 && std::string(argv[1]) == "--json"; if (argc != 2 && !json) { std::cerr << "usage: ribo-dataset-evaluate [--json] CASE.yaml\n"; return 2; } const auto c = readCase(argv[json ? 2 : 1]); const int s1 = c.stem1Length ? c.stem1Length : c.stemLength, s2 = c.stem2Length ? c.stem2Length : c.stemLength; if (c.id.empty() || c.sequence.empty() || c.reference.empty() || c.topology.empty()) { std::cerr << "error: dataset case requires id, sequence, reference_structure, and reference_topology\n"; return 1; } if (c.sequence.size() != c.reference.size()) { std::cerr << "error: sequence and reference_structure lengths differ\n"; return 1; } if (c.topology != "nested" && c.topology != "h_type_pseudoknot") { std::cerr << "error: declared topology '" << c.topology << "' requires an implemented crossing backend\n"; return 1; } try { const auto folded = c.topology == "h_type_pseudoknot" ? ribo::runtime::foldHType(c.sequence, c.minLoop, s1, s2, c.pairScore, c.wobbleScore) : ribo::runtime::foldNested(c.sequence, c.minLoop, c.pairScore, c.wobbleScore); const auto m = ribo::metrics::compareStructures(folded.structure, c.reference); if (!m.valid) { std::cerr << "error: reference_structure is malformed\n"; return 1; } if (c.topology == "nested" && m.referenceCrossing) { std::cerr << "error: reference_topology=nested contradicts crossing reference_structure\n"; return 1; } if (c.topology == "h_type_pseudoknot" && !m.referenceCrossing) { std::cerr << "error: reference_topology=h_type_pseudoknot requires crossing reference_structure\n"; return 1; } if (json) std::cout << "{\"schema\":\"ribo.dataset-metrics.v1\",\"id\":\"" << ribo::json::escape(c.id) << "\",\"topology\":\"" << ribo::json::escape(c.topology) << "\",\"min_loop\":" << c.minLoop << ",\"stem1_length\":" << s1 << ",\"stem2_length\":" << s2 << ",\"pair_score\":" << c.pairScore << ",\"wobble_score\":" << c.wobbleScore << ",\"score\":" << folded.score << ",\"structure\":\"" << ribo::json::escape(folded.structure) << "\",\"tp\":" << m.truePositive << ",\"fp\":" << m.falsePositive << ",\"fn\":" << m.falseNegative << ",\"sensitivity\":" << m.sensitivity() << ",\"ppv\":" << m.positivePredictiveValue() << ",\"f1\":" << m.f1() << "}\n"; else std::cout << "id=" << c.id << " source=" << c.source << " topology=" << c.topology << " min_loop=" << c.minLoop << " stem1_length=" << s1 << " stem2_length=" << s2 << " pair_score=" << c.pairScore << " wobble_score=" << c.wobbleScore << " score=" << folded.score << " structure=" << folded.structure << " tp=" << m.truePositive << " fp=" << m.falsePositive << " fn=" << m.falseNegative << " sensitivity=" << m.sensitivity() << " ppv=" << m.positivePredictiveValue() << " f1=" << m.f1() << "\n"; } catch (const std::exception &e) { std::cerr << "error: " << e.what() << "\n"; return 1; } }
